css:
:scope{display:block;width:100%}
:where(.pw p,.pw h1,.pw h2,.pw h3){margin:0;padding:0}
:where(.pw p,.pw li,.pw h1,.pw h2,.pw h3){text-wrap:wrap}
:where(.pw h1,.pw h2,.pw h3){color:inherit}
:where(.pw){overflow-wrap:normal}
.pw{--ink:#010A12;--bone:#EDE6D8;--stone:#E0D9CB;--sand:#BBAFA3;--oxblood:#321013;--mulberry:#5E3A3C;--clay:#8C5B46;--gilt:#C6A15B;--head:'Cormorant Garamond',serif;--body:'EB Garamond',serif;--label:'Montserrat',sans-serif;position:relative;background:var(--ink);color:var(--sand);padding:64px 0;font-family:var(--body);font-size:21px;line-height:1.5;font-weight:400;-webkit-font-smoothing:antialiased;text-align:left}
.pw *{box-sizing:border-box}
.in{max-width:1200px;margin:0 auto;padding:0 32px;display:grid;grid-template-columns:auto 1fr auto;gap:24px;align-items:center;font-family:var(--label);font-size:12px;letter-spacing:.24em;text-transform:uppercase}
.links{display:flex;gap:10px 22px;flex-wrap:wrap;justify-content:center;align-items:center}
.links a{color:var(--stone);text-decoration:underline;text-underline-offset:4px}
.r{text-align:right}
.r a{color:var(--sand);text-decoration:underline;text-underline-offset:4px}
.icons{display:inline-flex;gap:18px;margin-left:14px;align-items:center}
.icons a{display:inline-flex;width:44px;height:44px;align-items:center;justify-content:center;text-decoration:none;color:var(--stone);transition:color .3s}
.icons a:hover{color:var(--clay)}
.icons svg{width:22px;height:22px}
.icons svg *{fill:none;stroke:currentColor;stroke-width:1.3;stroke-linecap:round;stroke-linejoin:round}
.icons svg .f{fill:currentColor;stroke:none}
@media (max-width:767px){.in{padding:0 20px;grid-template-columns:1fr;text-align:left}.links{justify-content:flex-start}.r{text-align:left}}
@media (prefers-reduced-motion:reduce){.icons a{transition:none}}
